'use strict';
const fs=require('fs'),path=require('path'),Module=require('module'),crypto=require('crypto');
const snapshot=JSON.parse(fs.readFileSync(path.join(__dirname,'snapshots.json'),'utf8'));
const mode=process.argv[2],test=process.argv[3],source={...snapshot.snapshots[mode],...snapshot.inputs},accessed=new Set();
const sha=s=>crypto.createHash('sha256').update(s).digest('hex');
function key(file){try{return path.relative(snapshot.root,Buffer.isBuffer(file)?file.toString():file).replace(/\\/g,'/');}catch{return null;}}
const read=fs.readFileSync;fs.readFileSync=function(file,options){const p=key(file);if(Object.hasOwn(source,p)){accessed.add(p);const encoding=typeof options==='string'?options:options?.encoding;return encoding?Buffer.from(source[p]).toString(encoding):Buffer.from(source[p]);}return read.apply(this,arguments);};
for(const ext of ['.js','.cjs']){const original=Module._extensions[ext]||Module._extensions['.js'];Module._extensions[ext]=(m,file)=>{const p=key(file);if(Object.hasOwn(source,p)){accessed.add(p);m._compile(source[p],file);}else original(m,file);};}
const simplify=value=>typeof value==='string'&&value.length>2000?{type:'string',length:value.length,sha256:sha(value),prefix:value.slice(0,300),suffix:value.slice(-300)}:value;
process.on('uncaughtExceptionMonitor',error=>{
 process.stderr.write('\nBASELINE_ASSERTION_EVIDENCE '+JSON.stringify({name:error.name,message:error.message.length>2000?error.message.slice(0,2000):error.message,code:error.code,operator:error.operator,actual:simplify(error.actual),expected:simplify(error.expected),stack:error.stack?.slice(0,1800),accessedInputs:[...accessed].sort()})+'\n');
});
require(path.join(snapshot.root,test));

